entries[181006] = { ["name"] = "Blutritter beschwören", ["text"] = "Sofort\nLady Liadrin war der erste Paladin unter den Blutelfen, die Erste, die die Kraft des Lichts vom Naaru M'uru stahl, und die Erste, die Vergebung und Erlösung für ihr Volk anstrebte. Liadrin hat ihren Orden stets mit Stärke und Überzeugung geführt. Für sie haben die Blutritter nur ein einziges Ziel: dafür zu sorgen, dass die Brennende Legion ein für alle Mal besiegt wird." }
