entries[181009] = { ["name"] = "Anhänger: Maxwell Tyrosus", ["text"] = "Sofort\nLord Maxwell Tyrosus war einer der Ersten, die der Argentumdämmerung beitraten, und stieg im Orden schnell zu großem Ruhm auf, der nur dem Tirion Fordrings nachstand. Sowohl im Kampf gegen die Untoten von Naxxramas als auch gegen den Herrn der Geißel selbst ist Tyrosus stets ein standhafter Anführer und wahrer Champion des Lichts geblieben." }
