entries[181288] = { ["name"] = "Teufelsgefängnis", ["text"] = "Unbegrenzte Reichweite\nWirken in 2 sek.\nErzeugt einen Ring aus Teufelsenergie. Jede Kreatur, die in diesen Ring tritt, setzt die Energie frei, wodurch sich ein kristallines Teufelsgefängnis bildet. Ziele innerhalb von 8 Metern werden betäubt und ihr erlittener Schaden 30 Sek. lang um 99% verringert.\n\nDie Zerstörung des kristallinen Teufelsgefängnisses befreit alle darin gefangenen Ziele." }
