entries[181293] = { ["name"] = "Mächtige Teufelsflut", ["text"] = "Unbegrenzte Reichweite\nWirken in 3 sek.\nDer Zaubernde schlägt derart auf den Boden, dass alle drei Pfützen Tropfen aussenden. Ziele der Tropfen erleiden Schaden, der darauf basiert, von dem Tropfen welcher Pfütze sie getroffen wurden." }
