entries[181296] = { ["name"] = "Explosive Runen", ["text"] = "Unbegrenzte Reichweite\nWirken in 2 sek.\nDer Zaubernde erzeugt explosive Runen auf dem Boden. Wenn diese Runen nicht innerhalb von 15 Sek. ausgelöst werden, explodieren sie und fügen allen Gegnern 13839Feuerschaden zu.\n\nDas Auslösen der Rune führt zu einer kleineren Explosion, die dem Ziel 10399 Feuerschaden zufügt." }
entries[181297] = { ["name"] = "Mächtige explosive Runen", ["text"] = "Unbegrenzte Reichweite\nWirken in 2 sek.\nKormrok erzeugt mächtige explosive Runen auf dem Boden. Wenn diese Runen nicht innerhalb von 15 Sek. ausgelöst werden, explodieren sie und fügen allen Gegnern Feuerschaden zu.\n\nJedes Mal, wenn eine Rune ausgelöst wird, bewegt sie sich in die Richtung, in die der Spielercharakter blickt, der sie ausgelöst hat. Mächtige explosive Runen werden erst komplett verbraucht, wenn es sich bei ihnen um die letzte Rune im Spiel handelt oder ihre Bewegung sie auf die Position einer vorhandenen Rune führen würde." }
entries[181298] = { ["name"] = "Fel Lava Pillar Cosmetic" }
entries[181299] = { ["name"] = "Packende Hände", ["text"] = "Wirken in 2 sek.\nKormrok beschwört mehrere Steinhände unter den Füßen seiner Gegner, die allen Gegnern in einem Umkreis von 4 Metern um das Opfer 2301 körperlichen Schaden zufügen. Die Hände halten das Opfer fest, bis es vernichtet ist.\n\nWährend es gepackt ist, erleidet das Opfer alle 3 Sek. 3098 körperlichen Schaden." }
entries[181300] = { ["name"] = "Verschleppende Hände", ["text"] = "Wirken in 2 sek.\nKormrok beschwört mehrere Steinhände unter den Füßen seiner Gegner. Diese Hände zerren ihre Opfer zur nächsten Pfütze mit Teufelsenergie.\n\nWährend sie gepackt sind, erleiden Opfer alle 3 Sek. 35 körperlichen Schaden." }
