entries[181305] = { ["name"] = "Hinwegfegen", ["text"] = "10 Meter Reichweite\nWirken in 1 sek.\nKormrok stößt das Ziel nach hinten und fügt ihm 11504 Schattenschaden zu. Wenn das Opfer landet, erleidet es Schaden, der geringer ausfällt, je weiter es geflogen ist.\n\nDas Opfer wird mit 'Teuflische Berührung' belegt.\n\nTeuflische Berührung\nUnbegrenzte Reichweite\n\nSofort Das Opfer ist von Teufelsenergien betroffen, was seinen erlittenen magischen Schaden um 50% erhöht." }
entries[181306] = { ["name"] = "Explosive Eruption", ["text"] = "Unbegrenzte Reichweite\nSofort\nKormrok setzt den Boden unter den Füßen des Ziels in Brand und betäubt es. Nach 10 Sek. explodiert der Boden und fügt allen Spielercharakteren innerhalb von 30 Metern 13634 Feuerschaden zu.\n\nDas Opfer wird mit 'Teuflische Berührung' belegt.\n\nTeuflische Berührung\nUnbegrenzte Reichweite\n\nSofort Das Opfer ist von Teufelsenergien betroffen, was seinen erlittenen magischen Schaden um 50% erhöht." }
entries[181307] = { ["name"] = "Besudelter Brecher", ["text"] = "10 Meter Reichweite\nSofort\nKormrok beschwört eine Teufelshand unter dem Ziel. Das Opfer wird sofort ergriffen und zerquetscht, wodurch es jede Sekunde 2761 körperlichen Schaden erleidet, bis die Hand vernichtet wird.\n\nDas Opfer wird mit 'Teuflische Berührung' belegt.\n\nTeuflische Berührung\nUnbegrenzte Reichweite\n\nSofort Das Opfer ist von Teufelsenergien betroffen, was seinen erlittenen magischen Schaden um 50% erhöht." }
