entries[181647] = { ["name"] = "Stein des Windes", ["text"] = "Wirken in 3 sek.\nReagenzien:\nAlchemischer Katalysator (100), Magische Luft (5)\nVerkäufer:\nSamantha Scharlach\nGegenstand:\nFoliant der Steine\nKosten:\n10\nZone:\nMondsturz\n\nStein des Windes\nWird beim Aufheben gebunden\nEinzigartig anlegbar: Warlords - hergestellt (3)Schmuck\n+ 6 Vielseitigkeit\nAnlegen: Ihr habt eine Chance, bei hervorgerufener Heilung oder verursachtem Schaden Eure Stärke, Beweglichkeit oder Intelligenz 15 Sek. lang um 23 zu erhöhen. Es wird stets Euer höchster Wert gewählt. (Procchance: 35%, 55s Abklingzeit)\nAnlegen: Erhöht die Effekte, die Heil- und Manatränke auf den Träger haben, um 40%. Dieser Effekt ist nicht stapelbar.\n35\nBenötigt Alchemie von Draenor\n(1)\n\"Kann anstelle eines Steins der Weisen für Transmutationen verwendet werden.\"" }
entries[181648] = { ["name"] = "Stein der Erde", ["text"] = "Wirken in 3 sek.\nReagenzien:\nAlchemischer Katalysator (70), Wildblut (15), Stein des Windes , Magische Erde (15)\nVerkäufer:\nSamantha Scharlach\nGegenstand:\nFoliant der Steine\nKosten:\n10\nZone:\nMondsturz\n\nStein der Erde\nWird beim Aufheben gebunden\nEinzigartig anlegbar: Warlords - hergestellt (3)Schmuck\n+ 6 Vielseitigkeit\nAnlegen: Ihr habt eine Chance, bei hervorgerufener Heilung oder verursachtem Schaden Eure Stärke, Beweglichkeit oder Intelligenz 15 Sek. lang um 23 zu erhöhen. Es wird stets Euer höchster Wert gewählt. (Procchance: 35%, 55s Abklingzeit)\nAnlegen: Erhöht die Effekte, die Heil- und Manatränke auf den Träger haben, um 40%. Dieser Effekt ist nicht stapelbar.\n35\nBenötigt Alchemie von Draenor\n(1)\n\"Kann anstelle eines Steins der Weisen für Transmutationen verwendet werden.\"" }
